import { useEffect, useRef, useState } from 'react';
import { externalApi } from '../../../lib/api.js';
import { Page, Card } from './shared.jsx';
const button = 'border rounded-xl px-4 min-h-11 text-sm disabled:opacity-50';
export default function DiscoveryRewards() {
  const [portfolio, setPortfolio] = useState([]), [projects, setProjects] = useState([]), [rewards, setRewards] = useState(null), [error, setError] = useState(''), [message, setMessage] = useState(''), [busy, setBusy] = useState(false);
  const [form, setForm] = useState({ portfolioId: '', lat: '', lng: '', category: 'Wedding', style: 'Traditional', permission: false }), [file, setFile] = useState(null);
  const [locationQuery, setLocationQuery] = useState(''), [locations, setLocations] = useState([]);
  const uploadIntent = useRef(null);
  async function refresh() { const [p, d, r] = await Promise.all([externalApi.call('/vendor/portfolio'), externalApi.call('/vendor/discovery/projects'), externalApi.call('/vendor/rewards')]); setPortfolio(p.items || []); setProjects(d.projects || []); setRewards(r); }
  useEffect(() => { refresh().catch(e => setError(e.data?.message || e.message)); }, []);
  async function act(work) { setBusy(true); setError(''); setMessage(''); try { await work(); await refresh(); } catch (e) { setError(e.data?.message || e.message); } finally { setBusy(false); } }
  return <Page title="Discovery & rewards" sub="Submit approved inspiration and track achievements from saved business evidence."><div className="space-y-4">{error && <p role="alert" className="text-red-700">{error}</p>}{message && <p role="status" className="text-green-700">{message}</p>}
    {rewards && <Card title="Your achievement wallet"><p className="text-2xl font-bold">{rewards.xp} XP · {rewards.level.name}</p><p className="text-sm">{rewards.nextLevel ? `Next: ${rewards.nextLevel.name} at ${rewards.nextLevel.threshold} XP` : 'Highest level reached'}</p>{rewards.nextLevel && <progress className="w-full" aria-label="Progress toward next level" value={Math.max(0, rewards.xp - rewards.level.threshold)} max={rewards.nextLevel.threshold - rewards.level.threshold} />}<p className="text-xs text-muted">{rewards.policy ? `Rule version ${rewards.policy}` : 'No XP policy is active. Points begin after an approved policy is configured.'} XP and credits are separate. {rewards.note}</p><ul className="mt-3 space-y-2">{rewards.evidence.milestones.map(m => <li key={m.key} className="border rounded-xl p-3 text-sm">{m.complete ? '✓' : '○'} {m.label} · {m.evidence}</li>)}</ul><h3 className="font-bold mt-4">Achievement history</h3>{rewards.ledger.map(a => <p className="text-sm" key={a._id}>{a.milestone} · {a.xp} XP · {a.state} · {a.ruleVersion}</p>)}<p className="text-xs text-muted mt-2">{rewards.credits != null ? `${rewards.credits} redeemable growth credits available.` : 'Redeemable credits are not configured.'}</p></Card>}
    <Card title="Optional challenges"><p className="text-sm text-muted">These challenges use Core-verified completed bookings recorded during the challenge period. Each booking can support one challenge award; XP is capped per challenge.</p>{rewards?.challenges?.map(c => <div key={c._id} className="border rounded-xl p-3 mt-3"><p className="font-bold">{c.name}</p><p className="text-sm">{c.xp} XP · ends {new Date(c.end).toLocaleString()} · {c.status}</p>{c.status === 'AVAILABLE' && <button className={`${button} mt-2`} disabled={busy} onClick={() => act(async () => { const r = await externalApi.call(`/vendor/rewards/challenges/${c._id}/check`, { method: 'POST', body: {} }); setMessage(`Verified challenge: ${r.xp} XP ${r.state.toLowerCase()}.`); })}>Check verified completion</button>}</div>)}{rewards && !rewards.challenges?.length && <p className="text-sm mt-2">No active challenges.</p>}</Card>
    <Card title="Available benefits"><p className="text-sm text-muted">Non-cash benefits require current matching eligibility and an admin decision. XP is not spent when requesting a benefit.</p>{rewards?.benefits?.map(b => <div key={b._id} className="border rounded-xl p-3 mt-3"><h3 className="font-bold">{b.name}</h3><p className="text-sm">{b.description} · {b.minimumXp} XP required{b.creditValue ? ` · ${b.creditValue} Credits` : ''}{b.creditExpiryDays ? ` (Valid for ${b.creditExpiryDays}d)` : ''}</p>{b.redemptionInstructions && <p className="text-xs text-muted">{b.redemptionInstructions}</p>}<p className="text-sm">{b.status || (b.eligible ? 'Eligible to request' : 'Not currently eligible')}</p>{!b.status && <button className={`${button} mt-2`} disabled={busy || !b.eligible} onClick={() => act(async () => { await externalApi.call(`/vendor/rewards/benefits/${b._id}/request`, { method: 'POST', body: {} }); setMessage('Benefit request submitted for review.'); })}>Request benefit</button>}</div>)}{rewards && !rewards.benefits?.length && <p className="text-sm mt-2">No benefits are available yet.</p>}</Card>
    <Card title="Submit a project for anonymous discovery"><p className="text-sm text-muted">Upload an image or MP4 video you are permitted to share. Videos are limited to 30 seconds and have audio removed. Staff review the media for branding and identifying details before it can appear. Only event category, style and approximate distance are shown.</p><form className="grid sm:grid-cols-2 gap-3 mt-3" onSubmit={e => { e.preventDefault(); act(async () => { const fingerprint = JSON.stringify({ form, name: file.name, size: file.size, modified: file.lastModified }); if (uploadIntent.current?.fingerprint !== fingerprint) uploadIntent.current = { fingerprint, key: crypto.randomUUID() }; const body = new FormData(); Object.entries(form).forEach(([k,v]) => body.append(k, String(v))); body.append('file', file); body.append('idempotencyKey', uploadIntent.current.key); await externalApi.call('/vendor/discovery/projects', { method: 'POST', body }); setMessage('Project submitted for review.'); }); }}><label className="text-sm">Public portfolio item<select required className="block w-full border rounded-lg p-2" value={form.portfolioId} onChange={e => setForm({ ...form, portfolioId: e.target.value })}><option value="">Choose portfolio item</option>{portfolio.filter(p => p.visibility === 'PUBLIC' && ['PUBLISHED', 'VERIFIED', 'BOOKING_PROVEN'].includes(p.status)).map(p => <option key={p._id} value={p._id}>{p.title || p.projectName || p.mediaType}</option>)}</select></label><div className="sm:col-span-2"><label className="text-sm">Find project city or venue<input className="block w-full border rounded-lg p-2" value={locationQuery} onChange={e => setLocationQuery(e.target.value)} /></label><button type="button" className={`${button} mt-2`} disabled={busy || locationQuery.trim().length < 2} onClick={() => act(async () => { const r = await externalApi.call(`/vendor/google-places/search?q=${encodeURIComponent(locationQuery)}`); setLocations(r.places || []); })}>Search project location</button>{locations.map(p => <button type="button" className="block text-left underline text-primary min-h-11 text-sm" key={p.id} onClick={() => { if (Number.isFinite(p.lat) && Number.isFinite(p.lng)) { setForm({ ...form, lat: String(p.lat), lng: String(p.lng) }); setLocationQuery(p.name || p.address); setLocations([]); } }}>{p.name} · {p.address}</button>)}</div>{[['lat','Project latitude'],['lng','Project longitude']].map(([k,label]) => <label className="text-sm" key={k}>{label}<input required type="number" step="any" className="block w-full border rounded-lg p-2" value={form[k]} onChange={e => setForm({ ...form, [k]: e.target.value })} /></label>)}{[['category',['Wedding','Birthday','Corporate','Celebration','Other']],['style',['Traditional','Modern','Candid','Minimal','Classic','Other']]].map(([k,options]) => <label className="text-sm" key={k}>{k}<select className="block w-full border rounded-lg p-2" value={form[k]} onChange={e => setForm({ ...form, [k]: e.target.value })}>{options.map(v => <option key={v}>{v}</option>)}</select></label>)}<label className="text-sm">Image or MP4 video (up to 8 MB)<input required type="file" accept="image/jpeg,image/png,image/webp,video/mp4" className="block max-w-full" onChange={e => setFile(e.target.files?.[0])} /></label><label className="sm:col-span-2 flex items-center gap-3 text-sm"><input required type="checkbox" checked={form.permission} onChange={e => setForm({ ...form, permission: e.target.checked })} />I have the rights and permission to share this image anonymously.</label><button className={button} disabled={busy || !file}>Submit for review</button></form></Card>
    <Card title="Your discovery submissions">{projects.map(p => <div key={p._id} className="border rounded-xl p-3 mb-2 text-sm"><p>{p.category} · {p.style} · {p.status}</p>{p.status !== 'WITHDRAWN' && <button className={`${button} mt-2`} disabled={busy} onClick={() => act(async () => { await externalApi.call(`/vendor/discovery/projects/${p._id}/withdraw`, { method: 'POST', body: {} }); setMessage('Project withdrawn. Its discovery media is unavailable.'); })}>Withdraw project</button>}</div>)}{projects.length === 0 && <p>No submissions yet.</p>}</Card>
  </div></Page>;
}
